1	// scripts/demo-sicherung.mjs
2	//
3	// Sicherung und Wiederherstellung des Demo-Backends (NUR Demo-/Testdaten).
4	// Sichert den kompletten .data-Ordner (plattform.json, ki-nutzung.json,
5	// uploads/, kyc/ …) in einen Zeitstempel-Ordner unter .data-sicherungen/
6	// mit SHA-256-Manifest. Die Wiederherstellung prüft erst jedes Manifest-Hash
7	// und schreibt dann unter derselben Sperrdatei (plattform.lock), die auch das
8	// Demo-Backend benutzt – so kollidiert sie nicht mit dem laufenden Dev-Server.
9	//
10	// Aufrufe (im Projektordner):
11	//   node scripts/demo-sicherung.mjs sichern [name]
12	//   node scripts/demo-sicherung.mjs liste
13	//   node scripts/demo-sicherung.mjs pruefen <name>
14	//   node scripts/demo-sicherung.mjs wiederherstellen <name>
15	//
16	// Keine npm-Abhängigkeiten, nur node:fs / node:crypto / node:path.
17	
18	import { promises as fs, readFileSync, statSync } from "node:fs";
19	import { createHash } from "node:crypto";
20	import path from "node:path";
21	
22	const WURZEL = process.cwd();
23	const DATEN = path.join(WURZEL, ".data");
24	const ZIEL = path.join(WURZEL, ".data-sicherungen");
25	const SPERRE = path.join(DATEN, "plattform.lock");
26	
27	// Nie mitsichern: Sperrdatei und liegengebliebene atomare Schreib-Reste.
28	const AUSSCHLUSS = (rel) => rel === "plattform.lock" || /\.tmp$/.test(rel) || /plattform\.json\.\d+\.\d+\.tmp$/.test(rel);
29	
30	const warte = (ms) => new Promise((r) => setTimeout(r, ms));
31	
32	function sha256(buf) {
33	  return createHash("sha256").update(buf).digest("hex");
34	}
35	
36	async function dateienRekursiv(ordner, basis = ordner) {
37	  const liste = [];
38	  const eintraege = await fs.readdir(ordner, { withFileTypes: true });
39	  for (const e of eintraege) {
40	    const voll = path.join(ordner, e.name);
41	    if (e.isDirectory()) liste.push(...(await dateienRekursiv(voll, basis)));
42	    else if (e.isFile()) liste.push(path.relative(basis, voll).replaceAll("\\", "/"));
43	  }
44	  return liste.sort();
45	}
46	
47	// Dieselbe Sperrlogik wie src/lib/plattform/backend/demo/speicher.js, damit
48	// Wiederherstellung und laufender Dev-Server sich nicht in die Quere kommen.
49	function prozessLebt(pid) {
50	  if (!pid) return false;
51	  try {
52	    process.kill(pid, 0);
53	    return true;
54	  } catch (e) {
55	    return e.code === "EPERM";
56	  }
57	}
58	
59	async function sperren() {
60	  await fs.mkdir(DATEN, { recursive: true });
61	  const start = Date.now();
62	  for (;;) {
63	    try {
64	      const h = await fs.open(SPERRE, "wx");
65	      await h.writeFile(String(process.pid));
66	      await h.close();
67	      return;
68	    } catch (e) {
69	      if (e.code !== "EEXIST") throw e;
70	      try {
71	        const st = await fs.stat(SPERRE);
72	        const pid = Number(readFileSync(SPERRE, "utf8")) || 0;
73	        const alt = Date.now() - st.mtimeMs;
74	        if ((!prozessLebt(pid) && alt > 2000) || alt > 120000) await fs.rm(SPERRE, { force: true });
75	      } catch {
76	        /* inzwischen weg */
77	      }
78	      if (Date.now() - start > 60000) throw new Error("Demo-Datenbank ist gesperrt (Dev-Server beschäftigt) – später erneut versuchen");
79	      await warte(15 + Math.random() * 35);
80	    }
81	  }
82	}
83	
84	async function entsperren() {
85	  await fs.rm(SPERRE, { force: true }).catch(() => {});
86	}
