88	// Atomar schreiben (Datei + Umbenennen), mit Windows-Wiederholung wie im Demo-Backend.
89	async function atomarSchreiben(ziel, daten) {
90	  await fs.mkdir(path.dirname(ziel), { recursive: true });
91	  const tmp = `${ziel}.${process.pid}.${Date.now()}.tmp`;
92	  await fs.writeFile(tmp, daten);
93	  for (let i = 0; ; i++) {
94	    try {
95	      await fs.rename(tmp, ziel);
96	      return;
97	    } catch (e) {
98	      if (i > 20 || !["EPERM", "EBUSY", "EACCES"].includes(e.code)) {
99	        await fs.rm(tmp, { force: true }).catch(() => {});
100	        throw e;
101	      }
102	      await warte(15);
103	    }
104	  }
105	}
106	
107	async function sichern(name) {
108	  try {
109	    statSync(DATEN);
110	  } catch {
111	    console.error("Kein .data-Ordner vorhanden – nichts zu sichern.");
112	    process.exit(1);
113	  }
114	  const stempel = new Date().toISOString().replaceAll(":", "-").slice(0, 19);
115	  const ordnerName = name ? `${stempel}_${name.replace(/[^\w.-]+/g, "-")}` : stempel;
116	  const ziel = path.join(ZIEL, ordnerName);
117	  await fs.mkdir(ziel, { recursive: true });
118	
119	  const dateien = (await dateienRekursiv(DATEN)).filter((r) => !AUSSCHLUSS(r));
120	  const manifest = { erstellt: new Date().toISOString(), quelle: ".data", schemaHinweis: null, dateien: {} };
121	  let bytes = 0;
122	  for (const rel of dateien) {
123	    const daten = await fs.readFile(path.join(DATEN, rel));
124	    manifest.dateien[rel] = { sha256: sha256(daten), bytes: daten.length };
125	    bytes += daten.length;
126	    const zielDatei = path.join(ziel, rel);
127	    await fs.mkdir(path.dirname(zielDatei), { recursive: true });
128	    await fs.writeFile(zielDatei, daten);
129	    // Kopie sofort gegenlesen (Sichern-Verifizieren): Kopie muss dem Original gleichen.
130	    const kopie = await fs.readFile(zielDatei);
131	    if (sha256(kopie) !== manifest.dateien[rel].sha256) throw new Error(`Kopie weicht ab: ${rel}`);
132	  }
133	  try {
134	    manifest.schemaHinweis = JSON.parse(await fs.readFile(path.join(DATEN, "plattform.json"), "utf8")).schema ?? null;
135	  } catch {
136	    /* plattform.json fehlt oder gerade im Umbau – Hinweis bleibt leer */
137	  }
138	  await fs.writeFile(path.join(ziel, "manifest.json"), JSON.stringify(manifest, null, 1), "utf8");
139	  console.log(`Sicherung angelegt: .data-sicherungen/${ordnerName}`);
140	  console.log(`Dateien: ${dateien.length}, Umfang: ${(bytes / 1024 / 1024).toFixed(1)} MB, Schema: ${manifest.schemaHinweis}`);
141	  return ordnerName;
142	}
143	
144	async function manifestLesen(name) {
145	  const ordner = path.join(ZIEL, name);
146	  const manifest = JSON.parse(await fs.readFile(path.join(ordner, "manifest.json"), "utf8"));
147	  return { ordner, manifest };
148	}
149	
150	async function pruefen(name, still = false) {
151	  const { ordner, manifest } = await manifestLesen(name);
152	  const fehler = [];
153	  for (const [rel, soll] of Object.entries(manifest.dateien)) {
154	    try {
155	      const daten = await fs.readFile(path.join(ordner, rel));
156	      if (sha256(daten) !== soll.sha256) fehler.push(`Hash weicht ab: ${rel}`);
157	    } catch {
158	      fehler.push(`Datei fehlt: ${rel}`);
159	    }
160	  }
161	  if (fehler.length) {
162	    console.error(`Sicherung ${name} FEHLERHAFT:\n- ${fehler.join("\n- ")}`);
163	    process.exit(2);
164	  }
165	  if (!still) console.log(`Sicherung ${name} OK (${Object.keys(manifest.dateien).length} Dateien, alle SHA-256 stimmen).`);
166	  return manifest;
167	}
168	
169	async function wiederherstellen(name) {
170	  // 1. Erst die Sicherung selbst prüfen – eine kaputte Sicherung wird nie eingespielt.
171	  const manifest = await pruefen(name, true);
172	  const { ordner } = await manifestLesen(name);
173	
174	  // 2. Sicherheitsnetz: aktuellen Stand vor dem Überschreiben wegsichern.
175	  let netz = null;
176	  try {
177	    statSync(path.join(DATEN, "plattform.json"));
178	    netz = await sichern("vor-wiederherstellung");
179	  } catch {
180	    /* nichts da – z. B. echter Datenverlust */
181	  }
182	
183	  // 3. Unter der Sperre des Demo-Backends zurückschreiben (atomar je Datei).
184	  await sperren();
185	  try {
186	    for (const rel of Object.keys(manifest.dateien)) {
187	      const daten = await fs.readFile(path.join(ordner, rel));
188	      await atomarSchreiben(path.join(DATEN, rel), daten);
189	    }
190	  } finally {
191	    await entsperren();
192	  }
193	
194	  // 4. Nachkontrolle: eingespielter Stand gegen das Manifest.
195	  const fehler = [];
196	  for (const [rel, soll] of Object.entries(manifest.dateien)) {
197	    const daten = await fs.readFile(path.join(DATEN, rel));
198	    if (sha256(daten) !== soll.sha256) fehler.push(rel);
199	  }
200	  if (fehler.length) {
201	    console.error(`Nachkontrolle FEHLGESCHLAGEN (evtl. schreibt der Dev-Server gerade): ${fehler.join(", ")}`);
202	    console.error(netz ? `Vorheriger Stand liegt unter .data-sicherungen/${netz}` : "Kein vorheriger Stand vorhanden.");
203	    process.exit(3);
204	  }
205	  console.log(`Wiederherstellung aus ${name} abgeschlossen, Nachkontrolle OK (${Object.keys(manifest.dateien).length} Dateien).`);
206	  if (netz) console.log(`Stand davor gesichert als: .data-sicherungen/${netz}`);
207	  console.log("Hinweis: Laufender Dev-Server liest den neuen Stand automatisch (mtime-Cache).");
208	}
209	
210	async function liste() {
211	  let eintraege = [];
212	  try {
213	    eintraege = (await fs.readdir(ZIEL, { withFileTypes: true })).filter((e) => e.isDirectory()).map((e) => e.name).sort();
214	  } catch {
215	    /* noch keine Sicherungen */
216	  }
217	  if (!eintraege.length) return console.log("Keine Sicherungen unter .data-sicherungen/ vorhanden.");
218	  for (const name of eintraege) {
219	    try {
220	      const { manifest } = await manifestLesen(name);
221	      const bytes = Object.values(manifest.dateien).reduce((s, d) => s + d.bytes, 0);
222	      console.log(`${name}  –  ${Object.keys(manifest.dateien).length} Dateien, ${(bytes / 1024 / 1024).toFixed(1)} MB, Schema ${manifest.schemaHinweis}`);
223	    } catch {
224	      console.log(`${name}  –  (kein lesbares Manifest)`);
225	    }
226	  }
227	}
228	
229	const [befehl, name] = process.argv.slice(2);
230	try {
231	  if (befehl === "sichern") await sichern(name);
232	  else if (befehl === "liste") await liste();
233	  else if (befehl === "pruefen" && name) await pruefen(name);
234	  else if (befehl === "wiederherstellen" && name) await wiederherstellen(name);
235	  else {
236	    console.log("Aufruf: node scripts/demo-sicherung.mjs sichern [name] | liste | pruefen <name> | wiederherstellen <name>");
237	    process.exit(1);
238	  }
239	} catch (e) {
240	  console.error("Fehler:", e?.message || e);
241	  process.exit(1);
242	}
