1	// Prüft scripts/demo-sicherung.mjs vollständig isoliert: Das Skript läuft in
2	// einem Temp-Ordner mit eigener .data-Attrappe – die echte Demo-Datenbank und
3	// der laufende Dev-Server werden NICHT berührt.
4	import { test } from "node:test";
5	import assert from "node:assert/strict";
6	import { execFileSync } from "node:child_process";
7	import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync, existsSync, readdirSync } from "node:fs";
8	import { tmpdir } from "node:os";
9	import path from "node:path";
10	import { fileURLToPath } from "node:url";
11	
12	const SKRIPT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "scripts", "demo-sicherung.mjs");
13	
14	function lauf(cwd, ...args) {
15	  return execFileSync(process.execPath, [SKRIPT, ...args], { cwd, encoding: "utf8" });
16	}
17	
18	test("Demo-Sicherung: sichern, prüfen, Datenverlust, wiederherstellen", () => {
19	  const wurzel = mkdtempSync(path.join(tmpdir(), "demo-sicherung-"));
20	  try {
21	    const daten = path.join(wurzel, ".data");
22	    mkdirSync(path.join(daten, "uploads"), { recursive: true });
23	    const db = JSON.stringify({ schema: 2, konten: [{ id: "T-1", name: "Testkonto" }] });
24	    writeFileSync(path.join(daten, "plattform.json"), db);
25	    writeFileSync(path.join(daten, "uploads", "beleg.pdf"), "PDF-Attrappe");
26	    writeFileSync(path.join(daten, "plattform.lock"), "999999"); // darf NICHT mitgesichert werden
27	    writeFileSync(path.join(daten, "plattform.json.1.2.tmp"), "Rest"); // Schreibrest, auch nicht
28	
29	    // Sichern
30	    const aus = lauf(wurzel, "sichern", "test");
31	    assert.match(aus, /Sicherung angelegt/);
32	    const name = readdirSync(path.join(wurzel, ".data-sicherungen"))[0];
33	    const manifest = JSON.parse(readFileSync(path.join(wurzel, ".data-sicherungen", name, "manifest.json"), "utf8"));
34	    assert.deepEqual(Object.keys(manifest.dateien).sort(), ["plattform.json", "uploads/beleg.pdf"]);
35	    assert.equal(manifest.schemaHinweis, 2);
36	
37	    // Prüfen
38	    assert.match(lauf(wurzel, "pruefen", name), /OK/);
39	
40	    // Manipulierte Sicherung wird erkannt und NICHT eingespielt
41	    const kopie = path.join(wurzel, ".data-sicherungen", name, "plattform.json");
42	    const original = readFileSync(kopie, "utf8");
43	    writeFileSync(kopie, original + " ");
44	    assert.throws(() => lauf(wurzel, "wiederherstellen", name), /FEHLERHAFT|Hash/);
45	    writeFileSync(kopie, original);
46	
47	    // Datenverlust simulieren und wiederherstellen
48	    rmSync(path.join(daten, "plattform.json"));
49	    rmSync(path.join(daten, "uploads", "beleg.pdf"));
50	    assert.match(lauf(wurzel, "wiederherstellen", name), /Nachkontrolle OK/);
51	    assert.equal(readFileSync(path.join(daten, "plattform.json"), "utf8"), db);
52	    assert.equal(readFileSync(path.join(daten, "uploads", "beleg.pdf"), "utf8"), "PDF-Attrappe");
53	    assert.ok(!existsSync(path.join(daten, "plattform.lock")), "Sperre nach Wiederherstellung entfernt");
54	  } finally {
55	    rmSync(wurzel, { recursive: true, force: true });
56	  }
57	});
